import {PHOTO_BACKGROUNDS,PHOTO_POSES,PHOTO_COMPANIONS,PHOTO_CAST,PHOTO_MAX_COMPANIONS,photoCastLabel,WALL_SLOTS,MAX_PHOTOS} from './photo-config.js';import {createPhotoPreview} from './photo-scene.js';
const $=s=>document.querySelector(s);
const photoLabel=(p,i)=>`${i+1}. ${PHOTO_BACKGROUNDS[p.background].label} · ${photoCastLabel(p)}`;
export function openPhotoTools({ui,getProgress,transact,photoStore,savePhoto,createSession,createPreview=createPhotoPreview},{camera=true}={}){
 const options=(map,labels=false)=>Object.entries(map).map(([id,v])=>`<option value="${id}">${labels?v.label:v}</option>`).join('');let selected=getProgress().village.photos.at(-1)?.id??null;
 const capture=camera?`<p>도름이와 마을 친구들의 실제 3D 모습을 찍어요. 함께 찍기에서 단체사진을 고를 수 있어요. 기기 카메라나 외부 사진은 쓰지 않아요.</p><div class="photo-options"><label>배경<select id="photo-background">${options(PHOTO_BACKGROUNDS,true)}</select></label><label>포즈<select id="photo-pose">${options(PHOTO_POSES)}</select></label><label>함께 찍기<select id="photo-companion">${options(PHOTO_COMPANIONS)}<option value="group">단체로 친구 고르기</option></select></label></div><fieldset id="photo-group-choices" class="photo-group-choices" hidden><legend>함께 찍을 친구 · 도름이 포함 최대 7명</legend><div class="photo-cast-list">${Object.entries(PHOTO_CAST).map(([id,name],index)=>`<label><input type="checkbox" data-photo-cast="${id}" ${index<PHOTO_MAX_COMPANIONS?'checked':''}> ${name}</label>`).join('')}</div><p id="photo-group-count"></p><p class="caption">여러 명이면 앞뒤 두 줄로 서요. 앉기를 고르면 앞줄이 앉고 뒷줄은 단에 서요. 상점·학교·운동장·정원 친구는 익숙한 자세로 서서 함께 찍어요.</p></fieldset><div class="photo-preview"><canvas id="photo-canvas" width="640" height="480" aria-label="도름이와 친구의 3D 촬영 미리보기"></canvas><img id="photo-captured" alt="방금 찍은 도름이 사진" hidden></div><div class="modal-actions"><button id="photo-shoot" disabled>사진 찍기</button><button id="photo-frame" class="primary" disabled>이 사진을 액자로 만들기</button></div>`:'';
 return ui.workshop(camera?'찰칵 사진관 · 우리들의 한 장':'우리 집 · 벽의 작은 기억',`${capture}<p id="photo-status" role="status" aria-live="polite"></p><section><h3>내 사진 액자 <span id="photo-count"></span></h3><div id="photo-album" class="photo-album"></div><p id="photo-selected"></p><h3>걸어 둘 벽</h3><div class="choice-row">${Object.entries(WALL_SLOTS).map(([id,s])=>`<button data-wall="${id}">${s.label}</button>`).join('')}</div><div class="choice-row">${Object.entries(WALL_SLOTS).map(([id,s])=>`<button data-wall-remove="${id}">${s.label} 비우기</button>`).join('')}</div><div class="modal-actions"><button id="photo-download" class="secondary">사진 파일로 보관</button><button id="photo-remove" class="secondary">사진첩에서 빼기</button></div></section><p class="caption">사진첩은 최대 ${MAX_PHOTOS}장이에요. 사진과 배치는 이 브라우저에만 저장되고 밖으로 전송되지 않아요. 사이트 데이터를 지우거나 비공개 탐색을 닫으면 사라질 수 있어요. 사진 파일로 보관하면 기기에 JPEG가 내려받아져요. 이 파일은 게임 배치 복원용 백업은 아니에요.</p>`,()=>{
  let alive=true,preview=null,previewGeneration=0,pending=null,ready=false;const setStatus=text=>{if(alive)$('#photo-status').textContent=text;};
  function album(){if(!alive)return;const v=getProgress().village;if(!v.photos.some(p=>p.id===selected))selected=v.photos.at(-1)?.id??null;$('#photo-count').textContent=`${v.photos.length} / ${MAX_PHOTOS}`;$('#photo-album').innerHTML=v.photos.map((p,i)=>{const data=photoStore.get(p.id);return `<button data-photo="${p.id}" aria-pressed="${p.id===selected}">${data?`<img src="${data}" alt="${photoLabel(p,i)}">`:'<span class="photo-missing">사진 파일을 찾지 못했어요</span>'}<span>${photoLabel(p,i)}</span></button>`;}).join('')||'<p>사진관에서 첫 장을 찍어 보세요</p>';document.querySelectorAll('[data-photo]').forEach(b=>b.onclick=()=>{selected=b.dataset.photo;album();});const p=v.photos.find(p=>p.id===selected);$('#photo-selected').textContent=p?`고른 액자: ${photoLabel(p,v.photos.indexOf(p))}`:'먼저 사진을 골라 주세요';for(const b of document.querySelectorAll('[data-wall]')){b.disabled=!p||!photoStore.get(p.id);b.setAttribute('aria-pressed',String(v.wallPlacements[b.dataset.wall]===selected));}for(const b of document.querySelectorAll('[data-wall-remove]'))b.disabled=!v.wallPlacements[b.dataset.wallRemove];$('#photo-download').disabled=!p||!photoStore.get(p.id);$('#photo-remove').disabled=!p;if(camera){$('#photo-frame').disabled=!pending||v.photos.length>=MAX_PHOTOS;$('#photo-shoot').disabled=!ready||v.photos.length>=MAX_PHOTOS;}}
  document.querySelectorAll('[data-wall]').forEach(b=>b.onclick=()=>{if(!alive||!selected)return;const slotId=b.dataset.wall;if(getProgress().village.wallPlacements[slotId]===selected){setStatus('이미 이 벽에 걸려 있어요');return;}setStatus(transact({type:'PLACE_PHOTO',photoId:selected,slotId})?`${WALL_SLOTS[slotId].label}에 걸었어요. 집에 가서 확인해 보세요!`:'배치를 저장하지 못했어요');album();});document.querySelectorAll('[data-wall-remove]').forEach(b=>b.onclick=()=>{setStatus(transact({type:'REMOVE_WALL_PHOTO',slotId:b.dataset.wallRemove})?'벽을 비웠어요. 사진은 사진첩에 남아 있어요':'배치를 저장하지 못했어요');album();});
  $('#photo-download').onclick=()=>{const data=photoStore.get(selected);if(!alive||!data)return;const a=document.createElement('a');a.href=data;a.download='dormi-'+selected+'.jpg';a.click();setStatus('사진 파일 다운로드를 요청했어요. 기기의 다운로드 폴더를 확인해 주세요');};$('#photo-remove').onclick=()=>{if(!alive||!selected)return;setStatus(transact({type:'REMOVE_PHOTO',photoId:selected})?'사진첩에서 빼고 벽에서도 내렸어요':'사진첩을 저장하지 못했어요');pending=null;album();};
  if(camera){const choices=()=>{const group=$('#photo-companion').value==='group';return {background:$('#photo-background').value,pose:$('#photo-pose').value,companion:group?'none':$('#photo-companion').value,...(group?{companions:[...document.querySelectorAll('[data-photo-cast]')].filter(b=>b.checked).map(b=>b.dataset.photoCast)}:{})};};async function update(){if(!alive)return;const group=$('#photo-companion').value==='group';$('#photo-group-choices').hidden=!group;const count=group?choices().companions.length:0;for(const b of document.querySelectorAll('[data-photo-cast]'))b.disabled=!b.checked&&count>=PHOTO_MAX_COMPANIONS;$('#photo-group-count').textContent=group?`도름이와 친구 ${choices().companions.length}명 · 모두 ${choices().companions.length+1}명`:'';const token=++previewGeneration;pending=null;ready=false;$('#photo-captured').hidden=true;$('#photo-canvas').hidden=false;album();setStatus('도름이가 촬영 자리를 준비해요…');try{if(!preview)return;const done=await preview.update(choices());if(!alive||token!==previewGeneration)return;ready=done;setStatus(done?'준비됐어요! 사진 찍기를 눌러요':'촬영 준비를 다시 해 주세요');album();}catch{if(alive&&token===previewGeneration){ready=false;setStatus('3D 촬영 화면을 열지 못했어요. 창을 닫고 다시 시도해 주세요');album();}}}
   for(const b of document.querySelectorAll('[data-photo-cast]'))b.onchange=update;for(const id of ['photo-background','photo-pose','photo-companion'])$('#'+id).onchange=update;$('#photo-shoot').onclick=()=>{if(!alive||!ready)return;try{pending={data:preview.capture(),config:choices()};$('#photo-captured').src=pending.data;$('#photo-captured').hidden=false;$('#photo-canvas').hidden=true;setStatus('찰칵! 마음에 들면 액자로 만들어요');album();}catch{pending=null;setStatus('사진을 만들지 못했어요. 다시 찍어 주세요');album();}};$('#photo-frame').onclick=()=>{if(!alive||!pending)return;const result=savePhoto(pending.config,pending.data);if(result.ok){selected=result.id;pending=null;setStatus('액자를 만들었어요! 아래에서 걸어 둘 벽을 골라요');}else setStatus(result.message??'사진 저장에 실패했어요. 액자는 만들지 않았어요');album();};
   Promise.resolve().then(()=>!alive?null:createPreview($('#photo-canvas'),{session:createSession?.(),onFailure(){if(alive){ready=false;pending=null;setStatus('3D 연결이 끊겼어요. 다시 열어 주세요');album();}}})).then(p=>{if(!p)return;if(!alive){p.dispose();return;}preview=p;update();}).catch(()=>setStatus('이 기기에서 촬영 화면을 열지 못했어요. 사진첩은 계속 볼 수 있어요'));
  }
  album();return()=>{alive=false;previewGeneration++;pending=null;preview?.dispose();};
 });
}
